// Handle fork failure
if (pid == -1) {
    perror("fork");
    exit(EXIT_FAILURE);
}

// Child Process
if (pid == 0) {
    // Child executes first block
    printf("I am the child process (PID: %d)\n", getpid());
    _exit(0); // Use _exit() after fork()
}

// Parent Process
if (pid > 0) {
    int status;
    printf("I am the parent process (PID: %d), waiting...\n", getpid());
    waitpid(pid, &status, 0);
}
