// Common shell pattern: fork() then execve()
pid_t pid = fork();

if (pid == 0) {
    // Child: Replace itself with a new program
    char *const args[] = {"/bin/ls", "-l", "/tmp", NULL};
    execve(args[0], args, NULL);

    // Should not reach here
    _exit(127);
} else if (pid > 0) {
    // Parent: Wait for the child to finish
    wait(NULL);
}
